function semanticCache(host) {
    var state = { thr: 0.85 };
    var W = 520, H = 200, PAD = 26;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // deterministic incoming queries: cosine similarity to nearest cached entry,
    // and whether the cached answer is actually correct for that query
    var Q = [
      { sim: 0.97, ok: true }, { sim: 0.93, ok: true }, { sim: 0.90, ok: true },
      { sim: 0.88, ok: true }, { sim: 0.84, ok: false }, { sim: 0.80, ok: true },
      { sim: 0.76, ok: false }, { sim: 0.71, ok: false }, { sim: 0.62, ok: true },
      { sim: 0.50, ok: false }
    ];
    function px(s) { return PAD + (s - 0.4) / 0.6 * (W - 2 * PAD); }
    state._render = function () {
      var thr = state.thr;
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var tx = px(thr);
      svg.appendChild(svgEl('rect', { x: tx.toFixed(1), y: PAD, width: (W - PAD - tx).toFixed(1), height: (H - 2 * PAD).toFixed(1), fill: 'var(--blueprint,#3553ff)', opacity: '0.06' }));
      svg.appendChild(svgEl('line', { x1: tx, y1: PAD - 4, x2: tx, y2: H - PAD, stroke: 'var(--warn,#b8870f)', 'stroke-width': '1.5' }));
      var hits = 0, wrong = 0;
      Q.forEach(function (q, i) {
        var hit = q.sim >= thr;
        if (hit) { hits++; if (!q.ok) wrong++; }
        var cy = PAD + (i + 0.5) / Q.length * (H - 2 * PAD);
        var col = !hit ? 'var(--rule-soft,#ccc)' : (q.ok ? 'var(--blueprint,#3553ff)' : 'var(--warn,#b8870f)');
        svg.appendChild(svgEl('circle', { cx: px(q.sim), cy: cy.toFixed(1), r: hit ? '5' : '3.5', fill: col }));
      });
      num.innerHTML = hits + ' <small>of ' + Q.length + ' served from cache</small>';
      meta.textContent = 'threshold ' + thr.toFixed(2) + '  ·  ' + wrong + ' of those hits return a wrong answer  ·  ' + (thr >= 0.9 ? 'high: few hits, safe' : thr <= 0.7 ? 'low: many hits, risky' : 'balanced');
      formula.textContent = 'serve cached answer when cos(query, cached) ≥ ' + thr.toFixed(2) + '  ·  lower threshold = more hits, more risk';
    };
    var grid = el('div', {}, [slider(state, 'thr', 'similarity threshold', 0.5, 0.99, 0.01)]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['SEMANTIC CACHE']), el('span', {}, ['drag the threshold'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, num, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['A semantic cache answers a new query from a stored answer when their embeddings are close enough. Each dot is an incoming query placed by its cosine similarity to the nearest cached entry; the shaded zone past the orange line is served from cache. Raise the threshold and you get fewer hits but rarely serve a wrong answer; lower it and you cache more but risk returning a stale or mismatched reply (orange dots).'])
    ]));
    state._render();
  }

function guardrailGates(host) {
    var state = { trip: '0' };
    var W = 520, H = 150;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var status = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var gates = ['input filter', 'policy check', 'output filter'];
    var notes = ['blocked: malicious or off-policy prompt rejected before the model runs',
      'blocked: model output violates a usage policy',
      'blocked: unsafe content scrubbed from the response'];
    state._render = function () {
      var trip = Number(state.trip);
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      svg.appendChild(arrowDefs());
      var allowed = trip === 0;
      var bw = 110, gap = 22, x0 = 18, y = 44, h = 46;
      svg.appendChild(box(x0, y, 70, h, 'request', false));
      var prevX = x0 + 70, i;
      for (i = 0; i < 3; i++) {
        var gx = prevX + gap;
        var tripped = trip === i + 1;
        svg.appendChild(arrow(prevX, y + h / 2, gx, y + h / 2));
        svg.appendChild(box(gx, y, bw, h, gates[i], tripped));
        if (tripped) {
          var blockT = svgEl('text', { x: gx + bw / 2, y: y - 8, 'text-anchor': 'middle', 'font-family': 'var(--font-mono,monospace)', 'font-size': '11', fill: 'var(--warn,#b8870f)' });
          blockT.appendChild(document.createTextNode('BLOCK'));
          svg.appendChild(blockT);
        }
        prevX = gx + bw;
        if (tripped) { break; }
      }
      if (allowed) { svg.appendChild(arrow(prevX, y + h / 2, prevX + gap, y + h / 2)); svg.appendChild(box(prevX + gap, y, 80, h, 'allowed', false)); }
      status.innerHTML = allowed ? 'allowed' : 'blocked';
      meta.textContent = allowed ? 'all gates pass: the response is returned to the user' : notes[trip - 1];
    };
    var grid = el('div', {}, [LF.select(state, 'trip', 'which gate trips', [
      ['none / all pass', '0'], ['input filter', '1'], ['policy check', '2'], ['output filter', '3']
    ])]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['GUARDRAIL GATES']), el('span', {}, ['pick a gate'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, el('div', { style: 'margin-top:10px' }, [status]), meta])]),
      el('div', { class: 'lf-cap' }, ['Safety runs as ordered gates: an input filter before the model, a policy check on the request, and an output filter on the response. The first gate that trips blocks the request, so unsafe prompts never reach the model and unsafe outputs never reach the user.'])
    ]));
    state._render();
  }

function prodApp(host) {
    var svg = svgEl('svg', { viewBox: '0 0 520 250' });
    var g = svgEl('g');
    var stages = [[12, 62, 'request', SOFT], [100, 60, 'guard', BP], [186, 60, 'cache', BP], [272, 54, 'RAG', BP], [352, 50, 'LLM', BP], [428, 78, 'respond', INK]];
    g.appendChild(svgEl('line', { x1: 74, y1: 73, x2: 428, y2: 73, stroke: RULE, 'stroke-width': 1 }));
    var i;
    for (i = 0; i < 6; i++) {
      g.appendChild(box(stages[i][0], 58, stages[i][1], 30, stages[i][3]));
      g.appendChild(txt(stages[i][0] + stages[i][1] / 2, 77, stages[i][2], 9.5, stages[i][3], 'middle'));
    }
    g.appendChild(svgEl('path', { d: 'M 216 88 C 216 150 300 150 340 150 L 400 150 C 452 150 460 120 462 92', fill: 'none', stroke: RULE, 'stroke-width': 1.2, 'stroke-dasharray': '5 4' }));
    g.appendChild(txt(310, 164, 'cache hit shortcut', 8.5, MUTE, 'middle'));
    var missTag = txt(216, 50, 'miss', 8.5, WARN, 'middle');
    missTag.setAttribute('opacity', 0);
    missTag.appendChild(anim('opacity', '0;0;1;1;0;0', '6s', { keyTimes: '0;0.12;0.16;0.3;0.36;1' }));
    g.appendChild(missTag);
    var flash = svgEl('rect', { x: 186, y: 58, width: 60, height: 30, rx: 4, fill: BP, opacity: 0 });
    flash.appendChild(anim('opacity', '0;0;0.4;0;0', '6s', { keyTimes: '0;0.58;0.62;0.68;1' }));
    g.appendChild(flash);
    var miss = svgEl('circle', { r: 4.5, fill: BP, opacity: 0 });
    miss.appendChild(svgEl('animateMotion', { dur: '6s', repeatCount: 'indefinite', path: 'M 20 73 L 460 73', calcMode: 'linear', keyPoints: '0;1;1', keyTimes: '0;0.4;1' }));
    miss.appendChild(anim('opacity', '0;1;1;0;0', '6s', { keyTimes: '0;0.04;0.4;0.47;1' }));
    g.appendChild(miss);
    var hit = svgEl('circle', { r: 4.5, fill: BP, opacity: 0 });
    hit.appendChild(svgEl('animateMotion', { dur: '6s', repeatCount: 'indefinite', path: 'M 20 73 L 216 73 L 216 88 C 216 150 320 150 400 150 C 452 150 460 120 462 95', calcMode: 'linear', keyPoints: '0;0;1;1', keyTimes: '0;0.55;0.78;1' }));
    hit.appendChild(anim('opacity', '0;0;1;1;0;0', '6s', { keyTimes: '0;0.55;0.58;0.78;0.84;1' }));
    g.appendChild(hit);
    g.appendChild(txt(60, 208, 'miss', 9, SOFT, 'end'));
    g.appendChild(txt(60, 228, 'hit', 9, SOFT, 'end'));
    g.appendChild(svgEl('rect', { x: 72, y: 198, width: 240, height: 12, fill: 'none', stroke: RULE, 'stroke-width': 1 }));
    g.appendChild(svgEl('rect', { x: 72, y: 218, width: 240, height: 12, fill: 'none', stroke: RULE, 'stroke-width': 1 }));
    var mb = svgEl('rect', { x: 72, y: 198, width: 0, height: 12, fill: WARN });
    mb.appendChild(anim('width', '0;0;220;220;0', '6s', { calcMode: 'linear', keyTimes: '0;0.08;0.4;0.94;1' }));
    g.appendChild(mb);
    var hb = svgEl('rect', { x: 72, y: 218, width: 0, height: 12, fill: BP });
    hb.appendChild(anim('width', '0;0;14;14;0', '6s', { calcMode: 'linear', keyTimes: '0;0.55;0.78;0.94;1' }));
    g.appendChild(hb);
    g.appendChild(txt(320, 208, '~2 s, full token cost', 8.5, MUTE));
    g.appendChild(txt(320, 228, '~50 ms, free', 8.5, MUTE));
    entry(g, 260, 125);
    svg.appendChild(g);
    card(host, 'PRODUCTION LLM SERVICE', 'two requests, two very different paths', svg,
      'One request misses every cache and pays the full path: guardrails, retrieval, the model itself. Seconds of latency and full token cost. An identical request moments later short-circuits at the cache and returns in milliseconds for nearly nothing. Production LLM engineering is largely the work of making the second path the common one.');
  }

function mcpMatrix(host) {
    var svg = newSvg(250);
    var hosts = ['Claude', 'ChatGPT', 'Cursor'];
    var servers = ['db', 'calendar', 'files'];
    var hubX = 260, hubY = 125;
    // hub
    svg.appendChild(svgEl('circle', { cx: hubX, cy: hubY, r: 26, fill: BP, 'fill-opacity': '0.18', stroke: BP, 'stroke-width': '1.5' }));
    svg.appendChild(txt(hubX, hubY + 4, 'MCP', 11, BP, 'middle'));
    var hy = [50, 125, 200], sy = [50, 125, 200];
    hosts.forEach(function (h, i) {
      var hx = 40;
      svg.appendChild(svgEl('rect', { x: hx, y: hy[i] - 14, width: 76, height: 28, rx: 3, fill: 'var(--bg-surface,#eee)', stroke: SOFT, 'stroke-width': '1' }));
      svg.appendChild(txt(hx + 38, hy[i] + 4, h, 10, INK, 'middle'));
      svg.appendChild(svgEl('line', { x1: hx + 76, y1: hy[i], x2: hubX - 26, y2: hubY, stroke: SOFT, 'stroke-width': '1', 'stroke-dasharray': '5 4' }, [
        anim('stroke-dashoffset', '0;-18', '1.2s', { begin: (i * 0.3).toFixed(1) + 's' })
      ]));
      // request packet host → hub
      var pkt = svgEl('circle', { r: 5, fill: BP });
      pkt.appendChild(svgEl('animateMotion', { dur: '2.4s', repeatCount: 'indefinite', path: 'M ' + (hx + 76) + ' ' + hy[i] + ' L ' + (hubX - 26) + ' ' + hubY, begin: (i * 0.4).toFixed(1) + 's' }));
      pkt.appendChild(anim('opacity', '0;1;0', '2.4s', { begin: (i * 0.4).toFixed(1) + 's' }));
      svg.appendChild(pkt);
    });
    servers.forEach(function (sv, i) {
      var sx = 404;
      svg.appendChild(svgEl('rect', { x: sx, y: sy[i] - 14, width: 76, height: 28, rx: 3, fill: 'var(--bg-surface,#eee)', stroke: SOFT, 'stroke-width': '1' }));
      svg.appendChild(txt(sx + 38, sy[i] + 4, sv, 10, INK, 'middle'));
      svg.appendChild(svgEl('line', { x1: hubX + 26, y1: hubY, x2: sx, y2: sy[i], stroke: SOFT, 'stroke-width': '1', 'stroke-dasharray': '5 4' }, [
        anim('stroke-dashoffset', '0;-18', '1.2s', { begin: (i * 0.3 + 0.6).toFixed(1) + 's' })
      ]));
      var pkt2 = svgEl('circle', { r: 5, fill: WARN });
      pkt2.appendChild(svgEl('animateMotion', { dur: '2.4s', repeatCount: 'indefinite', path: 'M ' + (hubX + 26) + ' ' + hubY + ' L ' + sx + ' ' + sy[i], begin: (i * 0.4 + 1).toFixed(1) + 's' }));
      pkt2.appendChild(anim('opacity', '0;1;0', '2.4s', { begin: (i * 0.4 + 1).toFixed(1) + 's' }));
      svg.appendChild(pkt2);
    });
    svg.appendChild(txt(40, 232, 'N hosts', 10, MUTE));
    svg.appendChild(txt(404, 232, 'M servers', 10, MUTE));
    shell(host, 'MCP COLLAPSES N×M', 'one protocol, every host ↔ every server', svg,
      'Before MCP every host and every server spoke a bespoke protocol, an N×M integration matrix. MCP is one JSON-RPC spec in the middle: write one server and any compliant host discovers and calls its tools, resources, and prompts. Requests flow in, results flow back, through a single wire format.');
  }

function promptCacheHit(host) {
    var state = { prefix: 70, hit: 80 };
    var W = 520, H = 120, PAD = 20;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var bar = el('i');
    var barWrap = el('div', { class: 'lf-bar' }, [bar]);
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    state._render = function () {
      var pf = state.prefix / 100, hr = state.hit / 100;
      var saved = hr * pf;
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var inX = PAD, inW = W - 2 * PAD, y = 40, h = 40;
      var pw = inW * pf;
      svg.appendChild(svgEl('rect', { x: inX, y: y, width: pw.toFixed(1), height: h, rx: '3', fill: 'var(--bg-surface,#eee)', stroke: 'var(--blueprint,#3553ff)', 'stroke-width': '1.2', 'stroke-dasharray': '4 3' }));
      svg.appendChild(svgEl('rect', { x: (inX + pw).toFixed(1), y: y, width: (inW - pw).toFixed(1), height: h, rx: '3', fill: 'var(--blueprint,#3553ff)', opacity: '0.85' }));
      var t1 = svgEl('text', { x: (inX + pw / 2).toFixed(1), y: (y + h + 16).toFixed(1), 'text-anchor': 'middle', 'font-family': 'monospace', 'font-size': '10', fill: 'var(--ink-mute,#777)' });
      t1.appendChild(document.createTextNode('cached prefix ' + state.prefix + '%'));
      svg.appendChild(t1);
      var t2 = svgEl('text', { x: (inX + pw + (inW - pw) / 2).toFixed(1), y: (y + h + 16).toFixed(1), 'text-anchor': 'middle', 'font-family': 'monospace', 'font-size': '10', fill: 'var(--ink-soft,#555)' });
      t2.appendChild(document.createTextNode('new ' + (100 - state.prefix) + '%'));
      svg.appendChild(t2);
      num.innerHTML = (saved * 100).toFixed(1) + ' <small>% prefill saved</small>';
      bar.style.width = (saved * 100).toFixed(1) + '%';
      barWrap.classList.toggle('over', saved > 0.6);
      meta.textContent = 'hit rate ' + state.hit + '%  ·  cached prefix skips recompute  ·  cost and time-to-first-token both drop by ~' + (saved * 100).toFixed(0) + '%';
      formula.textContent = 'saved = hit_rate × prefix_fraction = ' + hr.toFixed(2) + ' × ' + pf.toFixed(2) + ' = ' + saved.toFixed(2);
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'prefix', 'shared prefix (% of prompt)', 0, 100, 1),
      slider(state, 'hit', 'cache hit rate (%)', 0, 100, 1)
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['PROMPT CACHE HIT']), el('span', {}, ['drag prefix and hit rate'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, num, barWrap, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['A long system prompt or document that repeats across calls can be prefilled once and reused. The cached prefix (dashed) skips recomputation, so only the new suffix (solid) is processed. The saving is the hit rate times the prefix fraction: a big shared prefix that is hit often is where caching pays off most.'])
    ]));
    state._render();
  }

function stateGraph(host) {
    var svg = svgEl('svg', { viewBox: '0 0 520 250' });
    var g = svgEl('g');
    var nodes = [[50, 70, 80, 'model', BP], [210, 26, 80, 'tools', BP], [210, 114, 80, 'human', WARN], [390, 114, 70, 'END', MUTE]];
    var i;
    for (i = 0; i < 4; i++) {
      g.appendChild(box(nodes[i][0], nodes[i][1], nodes[i][2], 32, nodes[i][4]));
      g.appendChild(txt(nodes[i][0] + nodes[i][2] / 2, nodes[i][1] + 20, nodes[i][3], 10, nodes[i][4], 'middle'));
    }
    g.appendChild(svgEl('line', { x1: 130, y1: 78, x2: 210, y2: 48, stroke: RULE, 'stroke-width': 1.2 }));
    g.appendChild(svgEl('line', { x1: 210, y1: 56, x2: 130, y2: 90, stroke: RULE, 'stroke-width': 1.2 }));
    g.appendChild(svgEl('line', { x1: 130, y1: 98, x2: 210, y2: 126, stroke: RULE, 'stroke-width': 1.2 }));
    g.appendChild(svgEl('line', { x1: 290, y1: 130, x2: 390, y2: 130, stroke: RULE, 'stroke-width': 1.2 }));
    var walker = svgEl('circle', { r: 5, fill: BP, opacity: 0 });
    walker.appendChild(svgEl('animateMotion', { dur: '6s', repeatCount: 'indefinite', path: 'M 90 86 L 250 42 L 90 86 L 250 130 L 425 130', calcMode: 'linear', keyPoints: '0;0.25;0.5;0.75;0.75;1;1', keyTimes: '0;0.15;0.3;0.45;0.72;0.88;1' }));
    walker.appendChild(anim('opacity', '0;1;1;0;0', '6s', { keyTimes: '0;0.04;0.88;0.94;1' }));
    g.appendChild(walker);
    var ring = svgEl('circle', { cx: 250, cy: 130, r: 24, fill: 'none', stroke: WARN, 'stroke-width': 1.5, opacity: 0 });
    ring.appendChild(anim('opacity', '0;0;0.9;0.9;0;0', '6s', { keyTimes: '0;0.48;0.52;0.68;0.74;1' }));
    g.appendChild(ring);
    var itx = txt(250, 172, 'interrupt: waiting for approval', 8.5, WARN, 'middle');
    itx.setAttribute('opacity', 0);
    itx.appendChild(anim('opacity', '0;0;1;1;0;0', '6s', { keyTimes: '0;0.48;0.52;0.68;0.74;1' }));
    g.appendChild(itx);
    g.appendChild(txt(60, 206, 'checkpointer', 9, MUTE));
    var cpAt = [0.15, 0.3, 0.45, 0.88];
    for (i = 0; i < 4; i++) {
      var cp = svgEl('rect', { x: 170 + i * 36, y: 194, width: 30, height: 16, rx: 2, fill: BP, opacity: 0 });
      cp.appendChild(anim('opacity', '0;0;0.8;0.8;0', '6s', { keyTimes: '0;' + cpAt[i] + ';' + (cpAt[i] + 0.04).toFixed(2) + ';0.94;1' }));
      g.appendChild(cp);
    }
    entry(g, 260, 125);
    svg.appendChild(g);
    card(host, 'AGENT STATE MACHINE', 'the loop becomes a graph you can pause', svg,
      'The same ReAct loop drawn as an explicit graph. The walker crosses model, tools, and human-approval nodes, and every transition writes a checkpoint to the ledger below. At the human node execution simply stops: state is already persisted, so the graph can resume later, or rewind to any earlier checkpoint and branch down a different path.');
  }

function frameworkFit(host) {
    var svg = svgEl('svg', { viewBox: '0 0 520 260' });
    var g = svgEl('g');
    g.appendChild(txt(260, 20, 'the whiteboard test: which shape is your problem?', 9.5, MUTE, 'middle'));
    function panel(x, y, name, tag, sketch, vals, times) {
      var p = svgEl('g', { opacity: 0.35 });
      p.appendChild(svgEl('rect', { x: x, y: y, width: 240, height: 102, fill: 'none', stroke: RULE, 'stroke-width': 1 }));
      p.appendChild(txt(x + 10, y + 20, name, 10.5, INK));
      p.appendChild(txt(x + 10, y + 92, tag, 8.5, MUTE));
      var i;
      for (i = 0; i < sketch.length; i++) { p.appendChild(sketch[i]); }
      p.appendChild(anim('opacity', vals, '6s', { keyTimes: times }));
      g.appendChild(p);
    }
    panel(10, 32, 'LangGraph', 'you draw a graph: typed state, edges', [
      svgEl('circle', { cx: 158, cy: 62, r: 7, fill: 'none', stroke: BP, 'stroke-width': 1.4 }),
      svgEl('circle', { cx: 204, cy: 84, r: 7, fill: 'none', stroke: BP, 'stroke-width': 1.4 }),
      svgEl('circle', { cx: 158, cy: 106, r: 7, fill: 'none', stroke: BP, 'stroke-width': 1.4 }),
      svgEl('line', { x1: 164, y1: 66, x2: 198, y2: 81, stroke: BP, 'stroke-width': 1.1 }),
      svgEl('line', { x1: 198, y1: 88, x2: 164, y2: 103, stroke: BP, 'stroke-width': 1.1 })
    ], '0.35;1;1;0.35;0.35', '0;0.03;0.21;0.26;1');
    panel(270, 32, 'CrewAI', 'you draw an org chart: roles + tasks', [
      svgEl('rect', { x: 420, y: 52, width: 36, height: 14, rx: 2, fill: 'none', stroke: BP, 'stroke-width': 1.4 }),
      svgEl('rect', { x: 396, y: 90, width: 32, height: 14, rx: 2, fill: SURF, stroke: MUTE, 'stroke-width': 1 }),
      svgEl('rect', { x: 448, y: 90, width: 32, height: 14, rx: 2, fill: SURF, stroke: MUTE, 'stroke-width': 1 }),
      svgEl('line', { x1: 432, y1: 66, x2: 412, y2: 90, stroke: MUTE, 'stroke-width': 1.1 }),
      svgEl('line', { x1: 444, y1: 66, x2: 464, y2: 90, stroke: MUTE, 'stroke-width': 1.1 })
    ], '0.35;0.35;1;1;0.35;0.35', '0;0.25;0.28;0.46;0.51;1');
    panel(10, 148, 'AutoGen', 'you draw a chat: agents take turns', [
      svgEl('rect', { x: 146, y: 174, width: 62, height: 18, rx: 9, fill: 'none', stroke: BP, 'stroke-width': 1.4 }),
      svgEl('rect', { x: 168, y: 202, width: 62, height: 18, rx: 9, fill: SURF, stroke: MUTE, 'stroke-width': 1 })
    ], '0.35;0.35;1;1;0.35;0.35', '0;0.5;0.53;0.71;0.76;1');
    panel(270, 148, 'Agno', 'you draw one box: agent + batteries', [
      svgEl('rect', { x: 418, y: 168, width: 50, height: 30, rx: 4, fill: 'none', stroke: BP, 'stroke-width': 1.4 }),
      svgEl('rect', { x: 414, y: 212, width: 12, height: 12, fill: SURF, stroke: MUTE, 'stroke-width': 1 }),
      svgEl('rect', { x: 436, y: 212, width: 12, height: 12, fill: SURF, stroke: MUTE, 'stroke-width': 1 }),
      svgEl('rect', { x: 458, y: 212, width: 12, height: 12, fill: SURF, stroke: MUTE, 'stroke-width': 1 })
    ], '0.35;0.35;1;1;0.35', '0;0.75;0.78;0.97;1');
    entry(g, 260, 130);
    svg.appendChild(g);
    card(host, 'FRAMEWORK TRADEOFFS', 'match the abstraction to the problem shape', svg,
      'Each framework has one core abstraction, and it is the thing you would draw on a whiteboard. LangGraph draws a state graph, CrewAI an org chart, AutoGen a conversation, Agno a single agent with tools attached. Pick the one whose drawing matches your problem; forcing the wrong shape means writing the missing abstraction yourself, twice.');
  }

